use vstd::prelude::*;

fn main() {}

verus!{

// File: defs.rs
pub struct Execution<T> {
    pub nat_to_state: spec_fn(nat) -> T,
}

impl<T> Execution<T> {

    pub open spec fn suffix(self, pos: nat) -> Self {
        Execution {
            nat_to_state: |i: nat| (self.nat_to_state)(i + pos),
        }
    }

}


#[verifier(reject_recursive_types(T))]
pub struct TempPred<T> {
    pub pred: spec_fn(Execution<T>) -> bool,
}

impl<T> TempPred<T> {

    pub open spec fn new(pred: spec_fn(Execution<T>) -> bool) -> Self {
        TempPred {
            pred: pred,
        }
    }

    pub open spec fn satisfied_by(self, execution: Execution<T>) -> bool {
        (self.pred)(execution)
    }

    pub open spec fn and(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) && other.satisfied_by(ex))
    }

    pub open spec fn implies(self, other: Self) -> Self {
        TempPred::new(|ex: Execution<T>| self.satisfied_by(ex) ==> other.satisfied_by(ex))
    }

    pub open spec fn leads_to(self, other: Self) -> Self {
        always(self.implies(eventually(other)))
    }

    pub open spec fn entails(self, other: Self) -> bool {
        valid(self.implies(other))
    }

}


pub open spec fn always<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| forall |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn eventually<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| exists |i: nat| #[trigger] temp_pred.satisfied_by(ex.suffix(i)))
}

pub open spec fn later<T>(temp_pred: TempPred<T>) -> TempPred<T> {
    TempPred::new(|ex: Execution<T>| temp_pred.satisfied_by(ex.suffix(1)))
}

pub open spec fn valid<T>(temp_pred: TempPred<T>) -> bool {
    forall |ex: Execution<T>| temp_pred.satisfied_by(ex)
}


// File: rules.rs
	#[verifier::external_body]
proof fn leads_to_unfold<T>(ex: Execution<T>, p: TempPred<T>, q: TempPred<T>)
    requires p.leads_to(q).satisfied_by(ex),
    ensures forall |i: nat| p.implies(eventually(q)).satisfied_by(#[trigger] ex.suffix(i)),
	{
		unimplemented!()
	}

	#[verifier::external_body]
proof fn implies_apply<T>(ex: Execution<T>, p: TempPred<T>, q: TempPred<T>)
    requires
        p.implies(q).satisfied_by(ex),
        p.satisfied_by(ex),
    ensures q.satisfied_by(ex),
	{
		unimplemented!()
	}

	#[verifier::external_body]
proof fn always_propagate_forwards<T>(ex: Execution<T>, p: TempPred<T>, i: nat)
    requires always(p).satisfied_by(ex),
    ensures always(p).satisfied_by(ex.suffix(i)),
	{
		unimplemented!()
	}

	#[verifier::external_body]
proof fn eventually_proved_by_witness<T>(ex: Execution<T>, p: TempPred<T>, witness_idx: nat)
    requires p.satisfied_by(ex.suffix(witness_idx)),
    ensures eventually(p).satisfied_by(ex)
	{
		unimplemented!()
	}

spec fn eventually_choose_witness<T>(ex: Execution<T>, p: TempPred<T>) -> nat
    recommends exists |i| p.satisfied_by(#[trigger] ex.suffix(i)),
{
    let witness = choose |i| p.satisfied_by(#[trigger] ex.suffix(i));
    witness
}

	#[verifier::external_body]
proof fn next_preserves_inv_rec<T>(ex: Execution<T>, next: TempPred<T>, inv: TempPred<T>, i: nat)
    requires
        inv.satisfied_by(ex),
        forall |idx| next.satisfied_by(#[trigger] ex.suffix(idx)),
        forall |idx| inv.satisfied_by(#[trigger] ex.suffix(idx)) && next.satisfied_by(ex.suffix(idx))
            ==> inv.satisfied_by(ex.suffix(idx + 1)),
    ensures inv.satisfied_by(ex.suffix(i)),
	{
		unimplemented!()
	}

	#[verifier::external_body]
pub proof fn execution_equality<T>(ex1: Execution<T>, ex2: Execution<T>)
    requires forall |i: nat| #[trigger] (ex1.nat_to_state)(i) == (ex2.nat_to_state)(i),
    ensures ex1 == ex2,
	{
		unimplemented!()
	}

// Helper: suffix composition
proof fn suffix_add<T>(ex: Execution<T>, i: nat, j: nat)
    ensures ex.suffix(i).suffix(j) == ex.suffix((i + j) as nat)
{
    assert(ex.suffix(i).suffix(j) == ex.suffix((i + j) as nat)) by {
        assert forall |k: nat| #[trigger] (ex.suffix(i).suffix(j).nat_to_state)(k)
            == (ex.suffix((i + j) as nat).nat_to_state)(k) by {
            // (ex.suffix(i).suffix(j).nat_to_state)(k)
            // = ex.suffix(i).nat_to_state(k + j)
            // = ex.nat_to_state(k + j + i)
            // = ex.nat_to_state(k + (i + j))
            // = ex.suffix(i+j).nat_to_state(k)
        };
        execution_equality(ex.suffix(i).suffix(j), ex.suffix((i + j) as nat));
    };
}

// Helper: once q holds at some suffix and q is stable under next, q always holds
proof fn q_stable_from<T>(
    ex: Execution<T>,
    next: TempPred<T>,
    q: TempPred<T>,
    start: nat
)
    requires
        q.satisfied_by(ex.suffix(start)),
        always(q.and(next).implies(later(q))).satisfied_by(ex),
        always(next).satisfied_by(ex),
    ensures
        always(q).satisfied_by(ex.suffix(start))
{
    // always(q).satisfied_by(ex.suffix(start))
    // = forall j: nat, q.satisfied_by(ex.suffix(start).suffix(j))
    // = forall j: nat, q.satisfied_by(ex.suffix(start + j))
    assert forall |j: nat| q.satisfied_by(#[trigger] ex.suffix(start).suffix(j)) by {
        suffix_add(ex, start, j);
        // Now we need: q.satisfied_by(ex.suffix(start + j))
        // Use next_preserves_inv_rec with ex2 = ex.suffix(start)
        // inv = q, next = next, ex2 = ex.suffix(start)
        // We need: 
        //   q.satisfied_by(ex.suffix(start))  [we have]
        //   forall idx, next.satisfied_by(ex.suffix(start).suffix(idx))
        //   forall idx, q /\ next at idx => q at idx+1

        // Get always(next) at ex.suffix(start)
        always_propagate_forwards(ex, next, start);
        // Now always(next).satisfied_by(ex.suffix(start))
        // So forall idx, next.satisfied_by(ex.suffix(start).suffix(idx))

        // Get always(q.and(next).implies(later(q))) at ex.suffix(start)
        always_propagate_forwards(ex, q.and(next).implies(later(q)), start);
        // always(q.and(next).implies(later(q))).satisfied_by(ex.suffix(start))
        // So forall idx, (q.and(next).implies(later(q))).satisfied_by(ex.suffix(start).suffix(idx))

        // Now apply next_preserves_inv_rec on ex.suffix(start) with inv = q
        assert forall |idx: nat| q.satisfied_by(#[trigger] ex.suffix(start).suffix(idx)) && next.satisfied_by(ex.suffix(start).suffix(idx))
            ==> q.satisfied_by(ex.suffix(start).suffix(idx + 1)) by {
            // From always(q.and(next).implies(later(q))).satisfied_by(ex.suffix(start))
            // we get (q.and(next).implies(later(q))).satisfied_by(ex.suffix(start).suffix(idx))
            // q.and(next).implies(later(q)).satisfied_by(ex.suffix(start).suffix(idx))
            // means: q.and(next).satisfied_by(ex.suffix(start).suffix(idx)) ==> later(q).satisfied_by(ex.suffix(start).suffix(idx))
            // later(q).satisfied_by(ex.suffix(start).suffix(idx))
            // = q.satisfied_by(ex.suffix(start).suffix(idx).suffix(1))
            // = q.satisfied_by(ex.suffix(start).suffix(idx + 1))
            suffix_add(ex.suffix(start), idx, 1);
        };

        next_preserves_inv_rec(ex.suffix(start), next, q, j);
    };
}

pub proof fn leads_to_stable<T>(spec: TempPred<T>, next: TempPred<T>, p: TempPred<T>, q: TempPred<T>)
    requires
        spec.entails(always(q.and(next).implies(later(q)))),
        spec.entails(always(next)),
        spec.entails(p.leads_to(q)),
    ensures spec.entails(p.leads_to(always(q))),
{
    assert forall |ex: Execution<T>| spec.implies(p.leads_to(always(q))).satisfied_by(ex) by {
        if spec.satisfied_by(ex) {
            // We have all three conditions for ex
            // spec.entails(always(q.and(next).implies(later(q)))) means:
            //   always(q.and(next).implies(later(q))).satisfied_by(ex)
            implies_apply(ex, spec, always(q.and(next).implies(later(q))));
            implies_apply(ex, spec, always(next));
            implies_apply(ex, spec, p.leads_to(q));

            // Now show p.leads_to(always(q)).satisfied_by(ex)
            // = always(p.implies(eventually(always(q)))).satisfied_by(ex)
            // = forall i, p.implies(eventually(always(q))).satisfied_by(ex.suffix(i))
            assert forall |i: nat| p.implies(eventually(always(q))).satisfied_by(#[trigger] ex.suffix(i)) by {
                if p.satisfied_by(ex.suffix(i)) {
                    // From p.leads_to(q) at ex, we know:
                    // forall i, p.implies(eventually(q)).satisfied_by(ex.suffix(i))
                    leads_to_unfold(ex, p, q);
                    // So p.implies(eventually(q)).satisfied_by(ex.suffix(i))
                    // Since p holds at ex.suffix(i), eventually(q) holds at ex.suffix(i)
                    implies_apply(ex.suffix(i), p, eventually(q));
                    // So there exists j such that q.satisfied_by(ex.suffix(i).suffix(j))
                    let j = eventually_choose_witness(ex.suffix(i), q);
                    // q holds at ex.suffix(i).suffix(j) = ex.suffix(i+j)

                    // Apply stability lemma: q is preserved once reached
                    // We need: always(q.and(next).implies(later(q))).satisfied_by(ex)
                    //          always(next).satisfied_by(ex)
                    // and q.satisfied_by(ex.suffix(i).suffix(j))
                    suffix_add(ex, i, j);
                    // ex.suffix(i).suffix(j) == ex.suffix(i+j)

                    q_stable_from(ex, next, q, (i + j) as nat);
                    // always(q).satisfied_by(ex.suffix(i+j))
                    // = always(q).satisfied_by(ex.suffix(i).suffix(j))

                    // So eventually(always(q)).satisfied_by(ex.suffix(i))
                    // with witness j
                    eventually_proved_by_witness(ex.suffix(i), always(q), j);
                }
            };
        }
    };
}


}
