            // From always(q.and(next).implies(later(q))).satisfied_by(ex.suffix(start))
            // we get (q.and(next).implies(later(q))).satisfied_by(ex.suffix(start).suffix(idx))
            // q.and(next).implies(later(q)).satisfied_by(ex.suffix(start).suffix(idx))
            // means: q.and(next).satisfied_by(ex.suffix(start).suffix(idx)) ==> later(q).satisfied_by(ex.suffix(start).suffix(idx))
            // later(q).satisfied_by(ex.suffix(start).suffix(idx))
            // = q.satisfied_by(ex.suffix(start).suffix(idx).suffix(1))
            // = q.satisfied_by(ex.suffix(start).suffix(idx + 1))
