                    // forall i, p.implies(eventually(q)).satisfied_by(ex.suffix(i))
                    leads_to_unfold(ex, p, q);
                    // So p.implies(eventually(q)).satisfied_by(ex.suffix(i))
                    // Since p holds at ex.suffix(i), eventually(q) holds at ex.suffix(i)
                    implies_apply(ex.suffix(i), p, eventually(q));
                    // So there exists j such that q.satisfied_by(ex.suffix(i).suffix(j))
                    let j = eventually_choose_witness(ex.suffix(i), q);
                    // q holds at ex.suffix(i).suffix(j) = ex.suffix(i+j)

                    // Apply stability lemma: q is preserved once reached
                    // We need: always(q.and(next).implies(later(q))).satisfied_by(ex)
                    //          always(next).satisfied_by(ex)
                    // and q.satisfied_by(ex.suffix(i).suffix(j))
                    suffix_add(ex, i, j);
                    // ex.suffix(i).suffix(j) == ex.suffix(i+j)

                    q_stable_from(ex, next, q, (i + j) as nat);
                    // always(q).satisfied_by(ex.suffix(i+j))
                    // = always(q).satisfied_by(ex.suffix(i).suffix(j))

                    // So eventually(always(q)).satisfied_by(ex.suffix(i))
                    // with witness j
                    eventually_proved_by_witness(ex.suffix(i), always(q), j);
                }
            };
        }
    };
}


